import java.sql.*;
public class AttendanceSettingsDAO {
 private static AttendanceSettings cached=new AttendanceSettings();
 public AttendanceSettings load(){try(Connection c=DBConnection.getConnection();PreparedStatement p=c==null?null:c.prepareStatement("SELECT rule_value FROM settings_attendance_leave_rules WHERE rule_name='ATTENDANCE:SETTINGS'")){if(p==null)return copy(cached);ResultSet r=p.executeQuery();if(r.next()){String[] v=r.getString(1).split("\\|",-1);if(v.length>=12){AttendanceSettings x=new AttendanceSettings();x.weeklyOffDays=Integer.parseInt(v[0]);x.publicHolidays=Integer.parseInt(v[1]);x.overtimeRatePerHour=Double.parseDouble(v[2]);x.attendanceBonusEnabled="1".equals(v[3]);x.attendanceThresholdPercent=Double.parseDouble(v[4]);x.attendanceBonusAmount=Double.parseDouble(v[5]);x.attendanceBonusPercent=Double.parseDouble(v[6]);x.bonusIsPercentage="1".equals(v[7]);x.lateArrivalGraceMinutes=Integer.parseInt(v[8]);x.halfDayCountsHalf="1".equals(v[9]);x.casualLeaveLimit=Integer.parseInt(v[10]);x.earnedLeaveLimit=Integer.parseInt(v[11]);if(v.length>=14){x.maximumClCarryForward=Math.max(0,Double.parseDouble(v[12]));x.maximumElCarryForward=Math.max(0,Double.parseDouble(v[13]));}cached=x;}}}catch(Exception ignored){}return copy(cached);}
 public void save(AttendanceSettings x)throws SQLException{if(x.maximumClCarryForward<0||x.maximumElCarryForward<0)throw new SQLException("Carry-forward limits cannot be negative.");Connection c=DBConnection.getConnection();if(c==null){cached=copy(x);return;}String v=x.weeklyOffDays+"|"+x.publicHolidays+"|"+x.overtimeRatePerHour+"|"+(x.attendanceBonusEnabled?1:0)+"|"+x.attendanceThresholdPercent+"|"+x.attendanceBonusAmount+"|"+x.attendanceBonusPercent+"|"+(x.bonusIsPercentage?1:0)+"|"+x.lateArrivalGraceMinutes+"|"+(x.halfDayCountsHalf?1:0)+"|"+x.casualLeaveLimit+"|"+x.earnedLeaveLimit+"|"+x.maximumClCarryForward+"|"+x.maximumElCarryForward;try(PreparedStatement p=c.prepareStatement("INSERT INTO settings_attendance_leave_rules(rule_name,rule_value) VALUES('ATTENDANCE:SETTINGS',?) ON CONFLICT(rule_name) DO UPDATE SET rule_value=excluded.rule_value")){p.setString(1,v);p.executeUpdate();cached=copy(x);}}
 private static AttendanceSettings copy(AttendanceSettings s){AttendanceSettings x=new AttendanceSettings();x.weeklyOffDays=s.weeklyOffDays;x.publicHolidays=s.publicHolidays;x.casualLeaveLimit=s.casualLeaveLimit;x.earnedLeaveLimit=s.earnedLeaveLimit;x.overtimeRatePerHour=s.overtimeRatePerHour;x.attendanceBonusAmount=s.attendanceBonusAmount;x.attendanceBonusPercent=s.attendanceBonusPercent;x.attendanceThresholdPercent=s.attendanceThresholdPercent;x.attendanceBonusEnabled=s.attendanceBonusEnabled;x.bonusIsPercentage=s.bonusIsPercentage;x.halfDayCountsHalf=s.halfDayCountsHalf;x.maximumClCarryForward=s.maximumClCarryForward;x.maximumElCarryForward=s.maximumElCarryForward;return x;}
}
